static NSError *MCPError(NSString *message){return TFAIError(470,message);}
static NSString *MCPPath(void){NSString *d=[NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:@"DylixAgent"];[NSFileManager.defaultManager createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];return [d stringByAppendingPathComponent:@"mcp.json"];}
static NSDictionary *HeaderQuery(NSString *identifier){return @{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrService:@"com.xuegao.dylix.mcp.headers.v1",(__bridge id)kSecAttrAccount:identifier};}
static NSDictionary *Headers(NSString *identifier){NSMutableDictionary *q=[HeaderQuery(identifier) mutableCopy];q[(__bridge id)kSecReturnData]=@YES;CFTypeRef result=NULL;if(SecItemCopyMatching((__bridge CFDictionaryRef)q,&result)!=errSecSuccess)return @{};NSData *d=CFBridgingRelease(result);id j=[NSJSONSerialization JSONObjectWithData:d options:0 error:nil];return [j isKindOfClass:NSDictionary.class]?j:@{};}
static BOOL LocalMCPHost(NSString *host){NSString *h=host.lowercaseString;if([h isEqual:@"localhost"]||[h hasSuffix:@".local"]||[h isEqual:@"::1"]||[h isEqual:@"[::1]"])return YES;struct in_addr a;if(inet_pton(AF_INET,h.UTF8String,&a)==1){uint32_t v=ntohl(a.s_addr);return (v>>24)==10||(v>>24)==127||(v>>16)==0xc0a8||(v>>20)==0xac1;}return NO;}
static BOOL StoreHeaders(NSString *identifier,NSDictionary *headers){NSMutableDictionary *q=[HeaderQuery(identifier) mutableCopy];NSData *d=[NSJSONSerialization dataWithJSONObject:headers options:0 error:nil];OSStatus status=SecItemUpdate((__bridge CFDictionaryRef)q,(__bridge CFDictionaryRef)@{(__bridge id)kSecValueData:d});if(status==errSecItemNotFound){q[(__bridge id)kSecValueData]=d;q[(__bridge id)kSecAttrAccessible]=(__bridge id)kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly;status=SecItemAdd((__bridge CFDictionaryRef)q,NULL);}return status==errSecSuccess;}
static NSString *ToolName(NSDictionary *server,NSDictionary *tool){NSString *raw=tool[@"name"],*identifier=server[@"id"];NSMutableString *safe=[NSMutableString new];NSCharacterSet *allowed=[NSCharacterSet characterSetWithCharactersInString:@"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"];for(NSUInteger i=0;i<raw.length&&safe.length<36;i++){unichar c=[raw characterAtIndex:i];[safe appendFormat:@"%C",[allowed characterIsMember:c]?c:'_'];}NSData *bytes=[[NSString stringWithFormat:@"%@\n%@",identifier,raw] dataUsingEncoding:NSUTF8StringEncoding];unsigned char hash[CC_SHA256_DIGEST_LENGTH];CC_SHA256(bytes.bytes,(CC_LONG)bytes.length,hash);return [NSString stringWithFormat:@"mcp_%@_%@_%02x%02x%02x%02x",[[identifier stringByReplacingOccurrencesOfString:@"-" withString:@""] substringToIndex:8],safe,hash[0],hash[1],hash[2],hash[3]];}
// One bounded POST exchange. A matching SSE reply completes immediately even if
// the server keeps its event stream open; no server-close dependency or key logs.
@interface TFAIMCPExchange : NSObject <NSURLSessionDataDelegate>
@property NSURLSession *session;
@property NSURLSessionDataTask *task;
@property NSMutableData *buffer;
@property NSString *requestID;
@property(copy) TFAIResult completion;
@property(copy) void(^receivedHeaders)(NSDictionary *);
@property BOOL terminal,notification,sse;
@property NSUInteger receivedBytes;
- (void)start:(NSURLRequest *)request;
@end
@implementation TFAIMCPExchange
- (void)finish:(NSDictionary *)result error:(NSError *)error{if(self.terminal)return;self.terminal=YES;TFAIResult done=self.completion;self.completion=nil;self.receivedHeaders=nil;[self.task cancel];[self.session invalidateAndCancel];self.task=nil;self.session=nil;self.buffer=nil;if(done)done(result,error);}
- (void)start:(NSURLRequest *)request{self.buffer=[NSMutableData new];NSURLSessionConfiguration *config=NSURLSessionConfiguration.ephemeralSessionConfiguration;config.HTTPCookieStorage=nil;config.HTTPShouldSetCookies=NO;config.URLCache=nil;config.timeoutIntervalForResource=45;self.session=[NSURLSession sessionWithConfiguration:config delegate:self delegateQueue:NSOperationQueue.mainQueue];self.task=[self.session dataTaskWithRequest:request];[self.task resume];}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task willPerformHTTPRedirection:(NSHTTPURLResponse *)response newRequest:(NSURLRequest *)request completionHandler:(void(^)(NSURLRequest *))completionHandler{completionHandler(nil);}
- (void)URLSession:(NSURLSession *)session dataTask:(NSURLSessionDataTask *)task didReceiveResponse:(NSURLResponse *)response completionHandler:(void(^)(NSURLSessionResponseDisposition))completionHandler{if(self.terminal){completionHandler(NSURLSessionResponseCancel);return;}NSHTTPURLResponse *http=(id)response;if(http.statusCode<200||http.statusCode>=300){completionHandler(NSURLSessionResponseCancel);[self finish:nil error:MCPError(DXLoc(@"MCP HTTP请求被拒绝，请检查服务和鉴权后重新发现。"))];return;}self.sse=[http.MIMEType.lowercaseString isEqual:@"text/event-stream"];if(self.receivedHeaders)self.receivedHeaders(http.allHeaderFields);completionHandler(NSURLSessionResponseAllow);if(self.notification&&http.statusCode==202)[self finish:@{} error:nil];}
- (BOOL)accept:(id)object{if(![object isKindOfClass:NSDictionary.class]||![object[@"id"] isEqual:self.requestID])return NO;if(![object[@"jsonrpc"] isEqual:@"2.0"]||object[@"error"]||![object[@"result"] isKindOfClass:NSDictionary.class]){[self finish:nil error:MCPError(DXLoc(@"MCP协议响应不完整或服务拒绝调用。"))];return YES;}[self finish:object[@"result"] error:nil];return YES;}
- (void)parseSSE{NSString *text=[[NSString alloc]initWithData:self.buffer encoding:NSUTF8StringEncoding];if(!text)return;NSMutableString *event=[NSMutableString new];NSArray *lines=[[[text stringByReplacingOccurrencesOfString:@"\r\n" withString:@"\n"] stringByAppendingString:@"\n\n"] componentsSeparatedByString:@"\n"];for(NSString *line in lines){if([line hasPrefix:@"data:"]){[event appendString:[line substringFromIndex:5]];[event appendString:@"\n"];}else if(!line.length&&event.length){id object=[NSJSONSerialization JSONObjectWithData:[event dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil];if([self accept:object])return;[event setString:@""];}}}
- (void)URLSession:(NSURLSession *)session dataTask:(NSURLSessionDataTask *)task didReceiveData:(NSData *)data{if(self.terminal)return;self.receivedBytes+=data.length;if(self.receivedBytes>8*1024*1024){[self finish:nil error:MCPError(DXLoc(@"MCP响应超出8MB，请缩小查询范围。"))];return;}[self.buffer appendData:data];if(self.sse&&!self.notification)[self parseSSE];}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task didCompleteWithError:(NSError *)error{if(self.terminal)return;if(error){[self finish:nil error:MCPError(DXLoc(@"MCP请求失败或超时，请检查服务后重新发现；凭据和响应详情未写入日志。"))];return;}if(self.notification){[self finish:@{} error:nil];return;}if(self.sse)[self parseSSE];else [self accept:[NSJSONSerialization JSONObjectWithData:self.buffer options:0 error:nil]];if(!self.terminal)[self finish:nil error:MCPError(DXLoc(@"MCP响应缺少匹配的JSON-RPC结果。"))];}
@end
@interface TFAIMCP () <NSURLSessionTaskDelegate>
@property NSMutableArray *records;
@property NSMutableDictionary *tools,*sessions,*wireSessions;
@end
@implementation TFAIMCP
+ (instancetype)shared{static id s;static dispatch_once_t once;dispatch_once(&once,^{s=[self new];});return s;}
- (instancetype)init{if((self=[super init])){id j=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:MCPPath()]?:NSData.data options:0 error:nil];_records=[NSMutableArray new];for(id row in [j isKindOfClass:NSArray.class]?j:@[]){if(![row isKindOfClass:NSDictionary.class]||![row[@"id"] isKindOfClass:NSString.class]||![[NSUUID alloc]initWithUUIDString:row[@"id"]]||![row[@"name"] isKindOfClass:NSString.class]||![row[@"url"] isKindOfClass:NSString.class]||![row[@"allowedTools"] isKindOfClass:NSArray.class])continue;NSURL *u=[NSURL URLWithString:row[@"url"]];if(![@[@"https",@"http"] containsObject:u.scheme.lowercaseString]||!u.host.length||u.user||u.password||u.query||u.fragment||([u.scheme.lowercaseString isEqual:@"http"]&&!LocalMCPHost(u.host)))continue;BOOL valid=YES;for(id tool in row[@"allowedTools"])if(![tool isKindOfClass:NSString.class])valid=NO;if(valid)[_records addObject:[row copy]];}_tools=[NSMutableDictionary new];_sessions=[NSMutableDictionary new];_wireSessions=[NSMutableDictionary new];}return self;}
- (NSArray *)servers{@synchronized(self){return [[NSArray alloc]initWithArray:self.records copyItems:YES];}}
- (BOOL)persist:(NSArray *)records error:(NSError **)error{NSData *d=[NSJSONSerialization dataWithJSONObject:records options:NSJSONWritingPrettyPrinted error:error];if(![d writeToFile:MCPPath() options:NSDataWritingAtomic error:error])return NO;self.records=[records mutableCopy];return YES;}
- (BOOL)importJSON:(NSString *)text error:(NSError **)error{@synchronized(self){id j=[NSJSONSerialization JSONObjectWithData:[text dataUsingEncoding:NSUTF8StringEncoding] options:0 error:error];id items=[j isKindOfClass:NSDictionary.class]?j[@"mcpServers"]:nil;if(![items isKindOfClass:NSDictionary.class]||[items count]>32){if(error)*error=MCPError(DXLoc(@"使用{mcpServers:{名称:{url,headers}}}格式，只接受HTTP服务。最多32项。Env、command、args与脚本不导入。"));return NO;}NSMutableArray *next=[self.records mutableCopy];NSMutableDictionary *secrets=[NSMutableDictionary new];for(id name in items){id row=items[name];NSURL *url=[row isKindOfClass:NSDictionary.class]&&[row[@"url"] isKindOfClass:NSString.class]?[NSURL URLWithString:row[@"url"]]:nil;BOOL scheme=[@[@"https",@"http"] containsObject:url.scheme.lowercaseString];if(![name isKindOfClass:NSString.class]||![name length]||[name length]>100||!url.host.length||!scheme||url.user||url.password||url.query||url.fragment||row[@"command"]||row[@"args"]||row[@"env"]){if(error)*error=MCPError(DXLoc(@"仅接受无账号、查询参数的HTTP(S) MCP URL，服务名应为1–100字。"));return NO;}if([url.scheme.lowercaseString isEqual:@"http"]&&!LocalMCPHost(url.host)){if(error)*error=MCPError(DXLoc(@"公网MCP使用HTTPS；HTTP仅限局域网地址。"));return NO;}
 NSMutableDictionary *header=[NSMutableDictionary new];if(row[@"headers"]&&![row[@"headers"] isKindOfClass:NSDictionary.class]){if(error)*error=MCPError(DXLoc(@"headers应为文本字典。"));return NO;}for(id k in row[@"headers"]){id value=row[@"headers"][k];if(![k isKindOfClass:NSString.class]||![value isKindOfClass:NSString.class]||[k rangeOfCharacterFromSet:NSCharacterSet.newlineCharacterSet].location!=NSNotFound||[value rangeOfCharacterFromSet:NSCharacterSet.newlineCharacterSet].location!=NSNotFound||[value length]>16384||[@[@"host",@"content-length",@"connection",@"cookie",@"origin",@"mcp-session-id"] containsObject:[k lowercaseString]]){if(error)*error=MCPError(DXLoc(@"MCP请求头无效或属于保留字段。"));return NO;}header[k]=value;}
 NSString *identifier=NSUUID.UUID.UUIDString;for(NSDictionary *old in next)if([old[@"name"] isEqual:name]){if(![old[@"url"] isEqual:url.absoluteString]){if(error)*error=MCPError(DXLoc(@"同名服务器地址不同，请删除旧项后明确重新授权。"));return NO;}identifier=old[@"id"];}
 NSDictionary *record=@{@"id":identifier,@"name":name,@"url":url.absoluteString,@"allowedTools":@[],@"revision":NSUUID.UUID.UUIDString};NSUInteger index=[next indexOfObjectPassingTest:^BOOL(NSDictionary *r,NSUInteger i,BOOL *stop){return [r[@"id"] isEqual:identifier];}];if(index==NSNotFound)[next addObject:record];else next[index]=record;secrets[identifier]=header;}
 NSMutableDictionary *oldHeaders=[NSMutableDictionary new];NSMutableArray *saved=[NSMutableArray new];BOOL ok=YES;for(NSString *identifier in secrets){oldHeaders[identifier]=Headers(identifier);if(!StoreHeaders(identifier,secrets[identifier])){ok=NO;break;}[saved addObject:identifier];}if(ok)ok=[self persist:next error:error];if(!ok){for(NSString *identifier in saved){if([oldHeaders[identifier] count])StoreHeaders(identifier,oldHeaders[identifier]);else SecItemDelete((__bridge CFDictionaryRef)HeaderQuery(identifier));}if(error&&!*error)*error=MCPError(DXLoc(@"MCP鉴权头或配置保存失败，原配置已回滚。"));return NO;}for(NSString *identifier in secrets){[self.tools removeObjectForKey:identifier];[self.wireSessions removeObjectForKey:identifier];for(NSMutableSet *set in self.sessions.allValues)[set removeObject:identifier];}return YES;}}
- (void)remove:(NSString *)identifier{@synchronized(self){NSMutableArray *n=[self.records mutableCopy];[n removeObjectsAtIndexes:[n indexesOfObjectsPassingTest:^BOOL(NSDictionary *r,NSUInteger i,BOOL *s){return [r[@"id"] isEqual:identifier];}]];if([self persist:n error:nil]){SecItemDelete((__bridge CFDictionaryRef)HeaderQuery(identifier));[self.tools removeObjectForKey:identifier];[self.wireSessions removeObjectForKey:identifier];for(NSMutableSet *set in self.sessions.allValues)[set removeObject:identifier];}}}
- (BOOL)enabled:(NSString *)identifier session:(NSString *)session{if(!session.length||!identifier.length)return NO;@synchronized(self){return [self.sessions[session] containsObject:identifier];}}
- (void)setEnabled:(BOOL)enabled server:(NSString *)identifier session:(NSString *)session{@synchronized(self){if(!session.length)return;if(!self.sessions[session])self.sessions[session]=[NSMutableSet new];if(enabled)[self.sessions[session] addObject:identifier];else[self.sessions[session] removeObject:identifier];}}
+ (BOOL)readOnlyTool:(NSDictionary *)tool{NSDictionary *a=[tool[@"annotations"] isKindOfClass:NSDictionary.class]?tool[@"annotations"]:@{};if(![a[@"readOnlyHint"] isEqual:@YES]||![a[@"destructiveHint"] isEqual:@NO])return NO;NSString *name=tool[@"name"];if(![name isKindOfClass:NSString.class]||!name.length||name.length>96)return NO;NSRegularExpression *danger=[NSRegularExpression regularExpressionWithPattern:@"(?i)(^|[_\\-.])(write|create|update|delete|remove|build|exec|execute|run|shell|push|pull|commit|stage|patch|upload|move|rename|set|insert|drop|alter)([_\\-.]|$)" options:0 error:nil];return ![danger firstMatchInString:name options:0 range:NSMakeRange(0,name.length)];}
- (BOOL)setAllowed:(BOOL)allowed tool:(NSString *)name server:(NSString *)identifier error:(NSError **)error{@synchronized(self){BOOL valid=NO;for(NSDictionary *tool in self.tools[identifier])if([tool[@"name"] isEqual:name]&&[TFAIMCP readOnlyTool:tool])valid=YES;if(!valid){if(error)*error=MCPError(DXLoc(@"只允许显式声明只读且无破坏性的查询工具。写项目、构建和Git继续使用Dylix原有审批。"));return NO;}NSMutableArray *next=[self.records mutableCopy];for(NSUInteger i=0;i<next.count;i++)if([next[i][@"id"] isEqual:identifier]){NSMutableDictionary *row=[next[i] mutableCopy];NSMutableSet *names=[NSMutableSet setWithArray:row[@"allowedTools"]?:@[]];if(allowed)[names addObject:name];else[names removeObject:name];row[@"allowedTools"]=names.allObjects;next[i]=row;}return [self persist:next error:error];}}
- (NSDictionary *)server:(NSString *)identifier{for(NSDictionary *row in self.servers)if([row[@"id"] isEqual:identifier])return row;return nil;}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task willPerformHTTPRedirection:(NSHTTPURLResponse *)response newRequest:(NSURLRequest *)request completionHandler:(void (^)(NSURLRequest *))completionHandler{completionHandler(nil);}
- (void)rpc:(NSDictionary *)server method:(NSString *)method params:(NSDictionary *)params notification:(BOOL)notification completion:(TFAIResult)completion{
 NSString *identifier=server[@"id"],*requestID=NSUUID.UUID.UUIDString;NSMutableDictionary *body=[@{@"jsonrpc":@"2.0",@"method":method} mutableCopy];if(params)body[@"params"]=params;if(!notification)body[@"id"]=requestID;NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:server[@"url"]]];r.HTTPMethod=@"POST";r.timeoutInterval=35;r.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:nil];for(NSString *k in Headers(identifier))[r setValue:Headers(identifier)[k] forHTTPHeaderField:k];[r setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];[r setValue:@"application/json, text/event-stream" forHTTPHeaderField:@"Accept"];[r setValue:@"2025-06-18" forHTTPHeaderField:@"MCP-Protocol-Version"];NSString *wire=self.wireSessions[identifier];if(wire)[r setValue:wire forHTTPHeaderField:@"Mcp-Session-Id"];
